def _bridge_user_id() -> int:
    """可选：把 QQ 来访都挂在哪个真实用户名下做审计/计费。0 = 不挂任何人。"""
    raw = _facade()._env("BUTLER_QQ_BRIDGE_USER_ID", "0")
    try:
        return max(int(raw), 0)
    except ValueError:
        return 0


