def is_configured() -> bool:
    """是否已经配齐能正常跑的最小凭证集合。"""
    return bool(_facade()._qq_app_id() and _facade()._qq_app_secret() and _facade()._qq_bot_token())


def _derive_seed(secret: str) -> bytes:
    raw = secret.encode("utf-8")
    if not raw:
        raise ValueError("BUTLER_QQ_APP_SECRET 不能为空")
    while len(raw) < 32:
        raw = raw + raw
    return raw[:32]


def _signing_key_for(app_secret: str):
    from nacl.signing import SigningKey

    return SigningKey(_facade()._derive_seed(app_secret))


def _signing_key():
    """默认（数字管家）签名密钥。"""
    return _facade()._signing_key_for(_facade()._qq_app_secret())


def sign_payload(payload: bytes) -> bytes:
    return _facade()._signing_key().sign(payload).signature


def _sign_payload_for(payload: bytes, app_secret: str) -> bytes:
    return _facade()._signing_key_for(app_secret).sign(payload).signature


def verify_inbound(timestamp: str, body: bytes, signature_hex: str) -> bool:
    return _facade()._verify_inbound_for(timestamp, body, signature_hex, _facade()._qq_app_secret())


def _verify_inbound_for(timestamp: str, body: bytes, signature_hex: str, app_secret: str) -> bool:
    from nacl.exceptions import BadSignatureError

    if not (timestamp and signature_hex):
        return False
    try:
        sig = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    msg = timestamp.encode("utf-8") + body
    verify_key = _facade()._signing_key_for(app_secret).verify_key
    try:
        verify_key.verify(msg, sig)
        return True
    except BadSignatureError:
        return False
    except RECOVERABLE_ERRORS:
        return False


def _all_known_app_secrets() -> _facade().Dict[str, str]:
    """返回 ``{app_id: app_secret}``：ENV 默认 + 账号池中所有 QQ 机器人 +
    两位老员工（``_SPECIFIC_WEBHOOKS``）的静态条目。

    前两个来源已经覆盖大多数情况，第三个来源只是兜底——保证 webhook
    在 DB 没建表 / 账号还没建好时，老员工的 op=13 握手与业务事件
    验签依然能跑通。
    """
    result: _facade().Dict[str, str] = {}
    default_id = _facade()._qq_app_id()
    default_secret = _facade()._qq_app_secret()
    if default_id and default_secret:
        result[default_id] = default_secret
    try:
        from modstore_server.ai_employee_account_secrets import read_secret
        from modstore_server.models import get_session_factory
        from modstore_server.models_ai_accounts import AIEmployeeAccount

        sf = get_session_factory()
        with sf() as session:
            rows = (
                session.query(AIEmployeeAccount)
                .filter(AIEmployeeAccount.platform == "qq", AIEmployeeAccount.status == "active")
                .all()
            )
        for row in rows:
            sec = read_secret(platform="qq", account_id=int(row.id))
            if sec:
                aid = str(sec.get("app_id") or row.external_id or "").strip()
                asecret = str(sec.get("app_secret") or "").strip()
                if aid and asecret:
                    result[aid] = asecret
    except RECOVERABLE_ERRORS as exc:
        _facade().logger.debug("_all_known_app_secrets 读账号池失败: %s", exc)
    for webhook_key, spec in _facade()._SPECIFIC_WEBHOOKS.items():
        aid = str(spec.get("app_id") or "").strip()
        if not aid:
            continue
        secret = _facade()._specific_app_secret(webhook_key)
        if secret:
            if result.get(aid) and result[aid] != secret:
                _facade().logger.info(
                    "QQ AppSecret 覆盖：app_id=%s 以 ENV/老员工专用解析为准（账号池值已忽略）", aid
                )
            result[aid] = secret
    return result


class _TokenState:
    __slots__ = ("token", "expires_at", "_lock")

    def __init__(self) -> None:
        self.token: str = ""
        self.expires_at: float = 0.0
        self._lock: _facade().Optional[_facade().asyncio.Lock] = None

    def _lock_or_create(self) -> _facade().asyncio.Lock:
        """Defer Lock() until an async caller has a running event loop (Py3.9 import-safe)."""
        if self._lock is None:
            self._lock = _facade().asyncio.Lock()
        return self._lock


"Implementation extracted from the public facade module."


async def get_access_token(force_refresh: bool = False) -> str:
    """取或刷新 AccessToken。提前 5 分钟续期，单飞防雪崩。"""
    now = _facade().time.time()
    if (
        not force_refresh
        and _facade()._token_state.token
        and (_facade()._token_state.expires_at - now > _facade()._TOKEN_REFRESH_LEAD_SECONDS)
    ):
        return _facade()._token_state.token
    async with _facade()._token_state._lock_or_create():
        now = _facade().time.time()
        if (
            not force_refresh
            and _facade()._token_state.token
            and (_facade()._token_state.expires_at - now > _facade()._TOKEN_REFRESH_LEAD_SECONDS)
        ):
            return _facade()._token_state.token
        app_id = _facade()._qq_app_id()
        app_secret = _facade()._qq_app_secret()
        if not (app_id and app_secret):
            raise _facade().HTTPException(503, "BUTLER_QQ_APP_ID / BUTLER_QQ_APP_SECRET 未配置")
        async with _facade().httpx.AsyncClient(timeout=15.0) as client:
            r = await client.post(
                _facade()._qq_token_endpoint(), json={"appId": app_id, "clientSecret": app_secret}
            )
            if r.status_code >= 400:
                raise _facade().HTTPException(
                    502, f"QQ getAppAccessToken 失败: {r.status_code} {r.text[:200]}"
                )
            data = r.json()
        token = str(data.get("access_token") or "").strip()
        if not token:
            raise _facade().HTTPException(502, f"QQ access_token 缺失：{data}")
        try:
            ttl = int(data.get("expires_in") or 7200)
        except RECOVERABLE_ERRORS:
            ttl = 7200
        _facade()._token_state.token = token
        _facade()._token_state.expires_at = now + max(ttl, 60)
        return token


"Implementation extracted from the public facade module."


class _SeqRegistry:
    """同一 ``msg_id`` 下 ``msg_seq`` 必须递增；进程内简单去重计数。"""

    def __init__(self) -> None:
        self._counts: _facade().Dict[str, int] = {}
        self._lock = _facade().asyncio.Lock()

    async def next(self, msg_id: str) -> int:
        if not msg_id:
            return 1
        async with self._lock:
            n = self._counts.get(msg_id, 0) + 1
            if n > 5:
                n = 5
            self._counts[msg_id] = n
            return n


"Implementation extracted from the public facade module."


async def _send(
    kind: _facade().MsgKind,
    target_id: str,
    content: str,
    *,
    msg_id: str = "",
    msg_seq: _facade().Optional[int] = None,
) -> _facade().Dict[str, _facade().Any]:
    """统一出站发送。``content`` 已是要展示的文本。"""
    if not target_id:
        raise _facade().HTTPException(400, "缺少 target_id")
    token = await _facade().get_access_token()
    base = _facade()._qq_api_base()
    if kind == "group":
        url = f"{base}/v2/groups/{target_id}/messages"
        body: _facade().Dict[str, _facade().Any] = {"content": content, "msg_type": 0}
    elif kind == "c2c":
        url = f"{base}/v2/users/{target_id}/messages"
        body = {"content": content, "msg_type": 0}
    elif kind == "channel":
        url = f"{base}/channels/{target_id}/messages"
        body = {"content": content}
    else:
        raise _facade().HTTPException(400, f"未知消息类型 kind={kind}")
    if msg_id:
        body["msg_id"] = msg_id
        if kind in ("group", "c2c"):
            body["msg_seq"] = msg_seq if msg_seq else await _facade()._seq_registry.next(msg_id)
    headers = {
        "Authorization": f"QQBot {token}",
        "Content-Type": "application/json",
        "X-Union-Appid": _facade()._qq_app_id(),
    }
    async with _facade().httpx.AsyncClient(timeout=15.0) as client:
        r = await client.post(url, headers=headers, json=body)
        if r.status_code == 401:
            await _facade().get_access_token(force_refresh=True)
            token = _facade()._token_state.token
            headers["Authorization"] = f"QQBot {token}"
            r = await client.post(url, headers=headers, json=body)
        if r.status_code >= 400:
            _facade().logger.warning(
                "QQ 出站失败 kind=%s url=%s status=%s body=%s",
                kind,
                url,
                r.status_code,
                r.text[:300],
            )
            raise _facade().HTTPException(r.status_code, f"QQ 接口失败: {r.text[:300]}")
        try:
            return r.json()
        except RECOVERABLE_ERRORS:
            return {"ok": True}


class _BotContext:
    """单个 QQ 机器人的运行时上下文（凭证 + token 缓存 + seq）。"""

    def __init__(
        self,
        employee_id: str,
        app_id: str,
        app_secret: str,
        sandbox: bool = False,
        bot_token: str = "",
    ) -> None:
        self.employee_id = employee_id
        self.app_id = app_id
        self.app_secret = app_secret
        self.sandbox = sandbox
        self._bot_token_static = (bot_token or "").strip()
        self._token = ""
        self._token_expires: float = 0.0
        self._lock = _facade().asyncio.Lock()
        self._seq = _facade()._SeqRegistry()

    def api_base(self) -> str:
        return "https://sandbox.api.sgroup.qq.com" if self.sandbox else "https://api.sgroup.qq.com"

    async def access_token(self, force: bool = False) -> str:
        if self._bot_token_static:
            return self._bot_token_static
        now = _facade().time.time()
        if not force and self._token and (self._token_expires - now > 300):
            return self._token
        async with self._lock:
            now = _facade().time.time()
            if not force and self._token and (self._token_expires - now > 300):
                return self._token
            async with _facade().httpx.AsyncClient(timeout=15.0) as c:
                r = await c.post(
                    _facade()._qq_token_endpoint(),
                    json={"appId": self.app_id, "clientSecret": self.app_secret},
                )
                d = r.json()
            tok = str(d.get("access_token") or "").strip()
            if not tok:
                raise RuntimeError(f"QQ token 获取失败 app_id={self.app_id}: {d}")
            self._token = tok
            self._token_expires = now + max(int(d.get("expires_in") or 7200), 60)
            return self._token

    async def send(
        self,
        kind: _facade().MsgKind,
        target_id: str,
        content: str,
        *,
        msg_id: str = "",
        msg_seq: _facade().Optional[int] = None,
    ) -> _facade().Dict[str, _facade().Any]:
        token = await self.access_token()
        base = self.api_base()
        if kind == "group":
            url = f"{base}/v2/groups/{target_id}/messages"
            body: _facade().Dict[str, _facade().Any] = {"content": content, "msg_type": 0}
        elif kind == "c2c":
            url = f"{base}/v2/users/{target_id}/messages"
            body = {"content": content, "msg_type": 0}
        else:
            url = f"{base}/channels/{target_id}/messages"
            body = {"content": content}
        if msg_id:
            body["msg_id"] = msg_id
            if kind in ("group", "c2c"):
                body["msg_seq"] = msg_seq if msg_seq else await self._seq.next(msg_id)
        headers = {
            "Authorization": f"QQBot {token}",
            "Content-Type": "application/json",
            "X-Union-Appid": self.app_id,
        }
        async with _facade().httpx.AsyncClient(timeout=15.0) as client:
            r = await client.post(url, headers=headers, json=body)
            if r.status_code == 401:
                token = await self.access_token(force=True)
                headers["Authorization"] = f"QQBot {token}"
                r = await client.post(url, headers=headers, json=body)
            if r.status_code >= 400:
                _facade().logger.warning(
                    "QQ 出站失败 app_id=%s kind=%s status=%s body=%s",
                    self.app_id,
                    kind,
                    r.status_code,
                    r.text[:300],
                )
                raise _facade().HTTPException(r.status_code, f"QQ 接口失败: {r.text[:300]}")
            try:
                return r.json()
            except RECOVERABLE_ERRORS:
                return {"ok": True}


